using System.Security.Claims; using MaintenancePRO.Api.Data; using MaintenancePRO.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace MaintenancePRO.Api.Controllers;
[ApiController,Route("api/dashboard"),Authorize]
public sealed class DashboardController(AppDbContext db):ControllerBase {
 [HttpGet] public async Task<IActionResult> Get(){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);var eq=db.Equipments.AsNoTracking();var br=db.Breakdowns.AsNoTracking();var iv=db.Interventions.AsNoTracking();if(User.IsInRole(AppRoles.User)){br=br.Where(x=>x.ReportedByUserId==uid);iv=iv.Where(x=>x.CreatedByUserId==uid);}else if(User.IsInRole(AppRoles.Technician)){iv=iv.Where(x=>x.AssignedTechnicianId==uid);br=br.Where(x=>x.ReportedByUserId==uid||x.Interventions.Any(i=>i.AssignedTechnicianId==uid));}
 var month=DateTime.UtcNow.AddDays(-30);return Ok(new{generatedUtc=DateTime.UtcNow,equipmentCount=await eq.CountAsync(x=>x.Status!=EquipmentStatus.Retired),brokenEquipment=await eq.CountAsync(x=>x.Status==EquipmentStatus.Broken),openBreakdowns=await br.CountAsync(x=>x.Status!=BreakdownStatus.Resolved&&x.Status!=BreakdownStatus.Closed&&x.Status!=BreakdownStatus.Rejected),criticalBreakdowns=await br.CountAsync(x=>x.Severity==BreakdownSeverity.Critical&&x.Status!=BreakdownStatus.Resolved&&x.Status!=BreakdownStatus.Closed),openInterventions=await iv.CountAsync(x=>x.Status!=InterventionStatus.Completed&&x.Status!=InterventionStatus.Cancelled&&x.Status!=InterventionStatus.Rejected),completedLast30Days=await iv.CountAsync(x=>x.Status==InterventionStatus.Completed&&x.CompletedUtc>=month),recentBreakdowns=await br.Include(x=>x.Equipment).OrderByDescending(x=>x.ReportedUtc).Take(5).Select(x=>new{id=x.Id,x.Title,x.Severity,x.Status,x.ReportedUtc,equipment=x.Equipment!.Name}).ToListAsync(),recentInterventions=await iv.Include(x=>x.Equipment).OrderByDescending(x=>x.CreatedUtc).Take(5).Select(x=>new{id=x.Id,x.Title,x.Status,x.CreatedUtc,equipment=x.Equipment!.Name}).ToListAsync()});}
 [HttpGet("reports"),Authorize(Policy="ManageMaintenance")] public async Task<IActionResult> Reports([FromQuery]DateTime? fromUtc,[FromQuery]DateTime? toUtc){var from=fromUtc??DateTime.UtcNow.AddDays(-30);var to=toUtc??DateTime.UtcNow;if(from>to||to-from>TimeSpan.FromDays(366))return BadRequest(new{message="Période invalide (maximum 366 jours)."});var breaks=db.Breakdowns.AsNoTracking().Where(x=>x.ReportedUtc>=from&&x.ReportedUtc<=to);var interventions=db.Interventions.AsNoTracking().Where(x=>x.CreatedUtc>=from&&x.CreatedUtc<=to);return Ok(new{fromUtc=from,toUtc=to,totalBreakdowns=await breaks.CountAsync(),resolvedBreakdowns=await breaks.CountAsync(x=>x.Status==BreakdownStatus.Resolved||x.Status==BreakdownStatus.Closed),totalInterventions=await interventions.CountAsync(),completedInterventions=await interventions.CountAsync(x=>x.Status==InterventionStatus.Completed),laborHours=await interventions.SumAsync(x=>x.LaborHours??0),totalCost=await interventions.SumAsync(x=>x.Cost??0),breakdownsBySeverity=await breaks.GroupBy(x=>x.Severity).Select(g=>new{severity=g.Key,count=g.Count()}).ToListAsync(),interventionsByStatus=await interventions.GroupBy(x=>x.Status).Select(g=>new{status=g.Key,count=g.Count()}).ToListAsync()});}
}
